// SERVER/routes/crud.js
w(path.join(B, 'server','routes','crud.js'), [
  "import { Router } from 'express';",
  "import pool from '../db.js';",
  "const router = Router();",
  "async function meta(tn) {",
  "  const [c]=await pool.query('SELECT COLUMN_NAME,DATA_TYPE,COLUMN_TYPE,IS_NULLABLE,EXTRA,COLUMN_KEY FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=\\'sas_agricolas\\' AND TABLE_NAME=? ORDER BY ORDINAL_POSITION',[tn]);",
  "  const pk=c.find(x=>x.EXTRA==='auto_increment'||x.COLUMN_KEY==='PRI');",
  "  return {columns:c,pk:pk?pk.COLUMN_NAME:c[0].COLUMN_NAME};",
  "}",
  "router.get('/:name/data', async (req,res) => {",
  "  try {",
  "    const tn=req.params.name,page=Math.max(1,parseInt(req.query.page)||1),ps=Math.min(100,Math.max(1,parseInt(req.query.pageSize)||20));",
  "    const search=req.query.search||'',sc=req.query.sortColumn||'',sd=(req.query.sortDirection||'ASC').toUpperCase();",
  "    const {columns,pk}=await meta(tn);",
  "    const vc=columns.map(c=>c.COLUMN_NAME);",
  "    const ssc=vc.includes(sc)?sc:pk;",
  "    const ssd=['ASC','DESC'].includes(sd)?sd:'ASC';",
  "    let wc='',sp=[];",
  "    if(search){",
  "      const tc=columns.filter(c=>['varchar','char','text','mediumtext','longtext','int','bigint','decimal','float','double','date','datetime','timestamp'].includes(c.DATA_TYPE));",
  "      if(tc.length>0){wc='WHERE '+tc.map(()=>'CAST(?? AS CHAR) LIKE ?').join(' OR ');const s='%'+search+'%';for(let i=0;i<tc.length;i++){sp.push(tc[i].COLUMN_NAME);sp.push(s);}}",
  "    }",
  "    const [cr]=await pool.query('SELECT COUNT(*) as total FROM ?? '+wc,[tn,...sp]);",
  "    const total=cr[0].total;",
  "    const off=(page-1)*ps;",
  "    const [rows]=await pool.query('SELECT * FROM ?? '+wc+' ORDER BY ?? '+ssd+' LIMIT ? OFFSET ?',[tn,...sp,ssc,ps,off]);",
  "    res.json({data:rows,pagination:{page,pageSize:ps,total,totalPages:Math.ceil(total/ps)}});",
  "  }catch(e){res.status(500).json({error:e.message});}",
  "});",
  "router.post('/:name/data', async (req,res) => {",
  "  try {",
  "    const {columns,pk}=await meta(req.params.name);",
  "    const ai=columns.filter(c=>c.EXTRA==='auto_increment').map(c=>c.COLUMN_NAME);",
  "    const f=[],pl=[],p=[];",
  "    for(const c of columns){if(ai.includes(c.COLUMN_NAME))continue;if(!(c.COLUMN_NAME in req.body))continue;if(req.body[c.COLUMN_NAME]===null||req.body[c.COLUMN_NAME]===undefined){if(c.IS_NULLABLE==='YES'){f.push('??');pl.push('NULL');}continue;}f.push('??');pl.push('?');p.push(c.COLUMN_NAME);p.push(req.body[c.COLUMN_NAME]);}",
  "    if(f.length===0)return res.status(400).json({error:'No campos'});",
  "    const [r]=await pool.query('INSERT INTO ?? ('+f.join(',')+') VALUES ('+pl.join(',')+')',[req.params.name,...p]);",
  "    res.json({success:true,insertId:r.insertId});",
  "  }catch(e){res.status(500).json({error:e.message});}",
  "});",
  "router.put('/:name/data/:id', async (req,res) => {",
  "  try {",
  "    const {columns,pk}=await meta(req.params.name);const id=req.params.id;",
  "    const sc=[],p=[];",
  "    for(const c of columns){if(c.COLUMN_NAME===pk&&columns.find(x=>x.EXTRA==='auto_increment')?.COLUMN_NAME===pk)continue;if(!(c.COLUMN_NAME in req.body))continue;sc.push('?? = ?');p.push(c.COLUMN_NAME);p.push(req.body[c.COLUMN_NAME]===undefined?null:req.body[c.COLUMN_NAME]);}",
  "    if(sc.length===0)return res.status(400).json({error:'No campos'});",
  "    p.push(id);",
  "    await pool.query('UPDATE ?? SET '+sc.join(',')+' WHERE ?? = ?',[req.params.name,...p]);",
  "    res.json({success:true});",
  "  }catch(e){res.status(500).json({error:e.message});}",
  "});",
  "router.delete('/:name/data/:id', async (req,res) => {",
  "  try { const {pk}=await meta(req.params.name); const [r]=await pool.query('DELETE FROM ?? WHERE ?? = ?',[req.params.name,pk,req.params.id]); res.json({success:true}); }",
  "  catch(e){res.status(500).json({error:e.message});}",
  "});",
  "router.get('/:name/lookup/:fkCol', async (req,res) => {",
  "  try {",
  "    const [fks]=await pool.query('SELECT REFERENCED_TABLE_NAME,REFERENCED_COLUMN_NAME FROM INFORMATION_SCHEMA.KEY_COLUMN_USAGE WHERE TABLE_SCHEMA=\\'sas_agricolas\\' AND TABLE_NAME=? AND COLUMN_NAME=? AND REFERENCED_TABLE_NAME IS NOT NULL',[req.params.name,req.params.fkCol]);",
  "    if(fks.length===0)return res.status(404).json({error:'No FK'});",
  "    const rt=fks[0].REFERENCED_TABLE_NAME,rc=fks[0].REFERENCED_COLUMN_NAME;",
  "    const [dc]=await pool.query('SELECT COLUMN_NAME FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=\\'sas_agricolas\\' AND TABLE_NAME=? AND DATA_TYPE IN (\\'varchar\\',\\'char\\',\\'text\\') ORDER BY ORDINAL_POSITION LIMIT 1',[rt]);",
  "    const dd=dc.length>0?dc[0].COLUMN_NAME:rc;",
  "    const [rows]=await pool.query('SELECT ?? as id, ?? as display FROM ?? ORDER BY ?? LIMIT 500',[rc,dd,rt,dd]);",
  "    res.json({table:rt,options:rows});",
  "  }catch(e){res.status(500).json({error:e.message});}",
  "});",
  "export default router;"
].join('\n'));

// src/utils/api.js - sin regex word boundary
w(path.join(B, 'src','utils','api.js'), [
  "const API = '/api';",
  "export const fetchModules = () => fetch(API+'/tables/modules').then(r=>r.json());",
  "export const fetchTableStructure = (t) => fetch(API+'/tables/'+encodeURIComponent(t)+'/structure').then(r=>{if(!r.ok)throw new Error('Error');return r.json();});",
  "export const fetchTableData = (t,{page=1,pageSize=20,search='',sortColumn='',sortDirection='ASC'}={}) => fetch(API+'/table/'+encodeURIComponent(t)+'/data?'+new URLSearchParams({page:String(page),pageSize:String(pageSize),search,sortColumn,sortDirection})).then(r=>{if(!r.ok)throw new Error('Error');return r.json();});",
  "export const insertRecord = (t,d) => fetch(API+'/table/'+encodeURIComponent(t)+'/data',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)}).then(r=>r.json());",
  "export const updateRecord = (t,id,d) => fetch(API+'/table/'+encodeURIComponent(t)+'/data/'+encodeURIComponent(id),{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)}).then(r=>r.json());",
  "export const deleteRecord = (t,id) => fetch(API+'/table/'+encodeURIComponent(t)+'/data/'+encodeURIComponent(id),{method:'DELETE'}).then(r=>r.json());",
  "export const fetchFKLookup = (t,fk) => fetch(API+'/table/'+encodeURIComponent(t)+'/lookup/'+encodeURIComponent(fk)).then(r=>r.json());",
  "export const fetchDashboardStats = () => fetch(API+'/dashboard/stats').then(r=>r.json());",
  "export const formatTableName = (n) => n.split('_').map(w=>w.charAt(0).toUpperCase()+w.slice(1)).join(' ');",
  "export const formatColumnName = (n) => { let r=n.split('_').map(w=>w==='id'||w==='pk'||w==='fk'?w.toUpperCase():w.charAt(0).toUpperCase()+w.slice(1)).join(' '); return r; };"
].join('\n'));

// src/utils/exportPdf.js
w(path.join(B, 'src','utils','exportPdf.js'), [
  "import jsPDF from 'jspdf';",
  "import 'jspdf-autotable';",
  "export function exportToPdf(tableName, columns, data) {",
  "  try {",
  "    const doc = new jsPDF({orientation:'landscape'});",
  "    const title = tableName.split('_').map(w=>w.charAt(0).toUpperCase()+w.slice(1)).join(' ');",
  "    doc.setFontSize(16);doc.setTextColor(26,35,50);",
  "    doc.text('SAS Agricolas - '+title, 14, 20);",
  "    doc.setFontSize(10);doc.setTextColor(100);",
  "    doc.text('Exportado: '+new Date().toLocaleString('es-ES'), 14, 28);",
  "    doc.text('Registros: '+data.length, 14, 34);",
  "    const headers = columns.map(c=>c.name.split('_').map(w=>w.charAt(0).toUpperCase()+w.slice(1)).join(' '));",
  "    const rows = data.map(row=>columns.map(col=>{const v=row[col.name];if(v===null||v===undefined)return '';if(typeof v==='object')return JSON.stringify(v);return String(v);}));",
  "    doc.autoTable({head:[headers],body:rows,startY:40,styles:{fontSize:7,cellPadding:2},headStyles:{fillColor:[26,35,50],textColor:[255,255,255],fontStyle:'bold'},alternateRowStyles:{fillColor:[245,247,250]},margin:{top:40}});",
  "    const pc=doc.internal.getNumberOfPages();",
  "    for(let i=1;i<=pc;i++){doc.setPage(i);doc.setFontSize(8);doc.setTextColor(150);doc.text('Pagina '+i+' de '+pc,doc.internal.pageSize.getWidth()/2,doc.internal.pageSize.getHeight()-10,{align:'center'});}",
  "    doc.save(tableName+'_'+new Date().toISOString().slice(0,10)+'.pdf');",
  "  } catch(e){alert('Error PDF: '+e.message);}",
  "}"
].join('\n'));

// src/utils/exportExcel.js
w(path.join(B, 'src','utils','exportExcel.js'), [
  "import * as XLSX from 'xlsx';",
  "export function exportToExcel(tableName, columns, data) {",
  "  try {",
  "    const headers = columns.map(c=>c.name.split('_').map(w=>w.charAt(0).toUpperCase()+w.slice(1)).join(' '));",
  "    const rows = data.map(row=>{const rd={};columns.forEach(col=>{const h=col.name.split('_').map(w=>w.charAt(0).toUpperCase()+w.slice(1)).join(' ');rd[h]=row[col.name]==null?'':row[col.name];});return rd;});",
  "    const ws = XLSX.utils.json_to_sheet(rows,{header:headers});",
  "    ws['!cols'] = headers.map(h=>({wch:Math.max(h.length+2,12)}));",
  "    const wb = XLSX.utils.book_new();",
  "    XLSX.utils.book_append_sheet(wb, ws, tableName.slice(0,31));",
  "    XLSX.writeFile(wb, tableName+'_'+new Date().toISOString().slice(0,10)+'.xlsx');",
  "  } catch(e){alert('Error Excel: '+e.message);}",
  "}"
].join('\n'));

