  "      <div className='sidebar-search'><input type='text' placeholder={'Buscar en '+total+' tablas...'} value={search} onChange={e=>setSearch(e.target.value)}/></div>",
  "      <nav className='sidebar-nav'>",
  "        <div className={'table-item'+(!selectedTable?' active':'')} onClick={onNavigateHome} style={{paddingLeft:16,fontWeight:selectedTable?400:600}}><span style={{marginRight:8}}>Dashboard</span></div>",
