  "          <button className='hamburger-btn' onClick={()=>setSidebarOpen(!sidebarOpen)}>=</button>",
  "          <div className='top-bar-title'><span className='logo-icon'>SAS</span><h1>SAS Agricolas</h1></div>",
  "          <div className='top-bar-right'>{selectedTable&&<span style={{fontSize:14}}>Inicio / {selectedTable.replace(/_/g,' ')}</span>}</div>",
  "        </header>",
  "        <div className='content-area'>",
  "          {selectedTable?<DynamicCatalog tableName={selectedTable} key={selectedTable}/>:<Dashboard modules={modules} loading={loading} onSelectTable={setSelectedTable}/>}",
